public String readString() throws IOException {
    /* Read a 4‑byte big‑endian integer that specifies the length of the string,
     * then read that many bytes and decode them as UTF‑8. */
    int length = 0;
    for (int i = 0; i < 4; i++) {
        int b = in.read(); // `in` is the underlying InputStream
        if (b == -1) {
            throw new IOException("Unexpected EOF while reading string length");
        }
        length = (length << 8) | b;
    }

    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }

    byte[] buf = new byte[length];
    int pos = 0;
    while (pos < length) {
        int n = in.read(buf, pos, length - pos);
        if (n == -1) {
            throw new IOException("Unexpected EOF while reading string data");
        }
        pos += n;
    }

    return new String(buf, java.nio.charset.StandardCharsets.UTF_8);
