protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Prepare lists for vertices and edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    // If the tour is empty, return an empty path
    if (tour == null || tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, vertices, edges);
    }

    // Keep a mutable copy of the set of remaining edges
    Set<E> remaining = new HashSet<>(tour);

    // Pick an arbitrary starting edge
    E startEdge = remaining.iterator().next();
    remaining.remove(startEdge);

    // Start from the source of the starting edge
    V current = graph.getEdgeSource(startEdge);
    vertices.add(current);
    edges.add(startEdge);

    // Determine the initial next vertex
    V next = graph.getEdgeTarget(startEdge);
    if (!current.equals(next)) {
        current = next;
        vertices.add(current);
    }

    // Continue traversing until no remaining edges connect to the current vertex
    while (!remaining.isEmpty()) {
        E chosen = null;
        for (E e : remaining) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current) || tgt.equals(current)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) {
            // No connecting edge found; break out of loop
            break;
        }
        edges.add(chosen);
        remaining.remove(chosen);

        // Move to the next vertex along the chosen edge
        V src = graph.getEdgeSource(chosen);
        V tgt = graph.getEdgeTarget(chosen);
        current = src.equals(current) ? tgt : src;
        vertices.add(current);
    }

    return new DefaultGraphPath<>(graph, vertices, edges);
