    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long runningSum = 0;
    long[] temp = new long[n];
    for (int i = n - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        temp[i] = runningSum;
    }
    for (int i = 0; i < n; i++) {
        suffix.add((int) temp[i]);
    }
    long totalSum = runningSum;
    return new Pair<>(suffix, totalSum);
